import { people, cases } from './company-model.mjs';
import { renderCompanyMap } from './company-map.mjs';
import { renderWorkspace, employeeStrip } from './company-workspaces.mjs';
import { renderBuilds } from './company-builds.mjs';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const miro='https://miro.com/blog/state-of-intelligent-collaboration-2026/';
const atlassian='https://www.atlassian.com/blog/state-of-teams-2026';
export const scenes=[
 {title:'What Dana thinks is happening.',lead:'Parkside · A fictional 150-person company · Everyone has a Copilot license.'},
 {title:'Individual progress. A company-wide gap.',lead:'Three research findings explain why access alone is not the whole story.'},
 {title:'Meet the company.',lead:'Nine people. Different kinds of AI use. Click a person to sit beside them.'},
 {title:'See what people have figured out.',lead:'Explore Ben’s forecast review, Priya’s monthly reporting tool and Nina’s department bot.'},
 {title:'The same access. Very different needs.',lead:'Ava needs context. Elena needs a usable workflow. Marcus needs clarity and a way to share his technique.'},
 {title:'See the work between departments.',lead:'Leah gathers, compares and reconciles the updates before Dana ever opens her briefing.'},
 {title:'What we discover by sitting beside people.',lead:'Useful methods. Different needs. Information that does not reach the next person.'},
 {title:'Three things Nine-67 could build.',lead:'Reuse a proven method. Guide a real task. Connect reviewed findings to action.'},
 {title:'Look across the company. Choose where to build.',lead:'Company-wide discovery, a prioritized build plan, and implementation with the people doing the work.'}
];
export const cues=[
 'Josh: Dana sees real success, including her own. Open her Claude preparation to show why her confidence is reasonable.',
 'Josh: These are different surveys. People get more done; much of the work stays private; fewer people embed AI into workflows.',
 'Josh: Click any employee. The same license means nine different things. Switch the company view to preview one specific improvement.',
 'Josh: Run Priya’s refresh, Ben’s saved review or Nina’s bot. Ask who else could use what they have already built.',
 'Josh: This is not a motivation problem. Show Ava’s hidden preparation, Elena’s first attempt and Marcus’s private practice.',
 'Josh: Prepare the Friday brief. Compare the names, dates and assumptions. Then show the summary Dana actually receives.',
 'Josh: Start company-wide discovery before deciding what to build. Some work can be reused, some needs a guided workflow, and some needs a connection.',
 'Josh: Pick one of three builds. Show the input, the human review and the usable output. These are simulated workflows, not live integrations.',
 'Josh: Bring Operations, IT and two department leaders. One example where AI helps. One piece of work you still chase.'
];
function board(){return `<section class="opening-board"><div class="opening-copy"><small>PARKSIDE · CEO’S ROLLOUT UPDATE</small><h2>“We gave everyone AI.<br>I thought we were in pretty good shape.”</h2><p>Dana has seen Sales use it well. IT launched a company assistant. Claude helps her prepare for board meetings.</p><button class="primary" data-workspace="dana">Open Dana’s rollout and Claude session →</button></div><div class="opening-report"><header><img src="assets/ms-powerpoint.svg" alt=""> AI rollout · Board update</header><div><strong>150</strong><span>Copilot licenses assigned</span></div><div><strong>Live</strong><span>Ask Parkside company assistant</span></div><div><strong>Working</strong><span>Sales forecast review</span></div><p>What would we see if we sat beside the employees?</p></div></section>`;}
function research(){return `<div class="research-cards"><article><strong>83%</strong><h2>People get more done.</h2><p>Agree AI improves individual productivity.</p><span>A useful result for one person does not automatically become a company capability.</span><a href="${miro}" target="_blank" rel="noopener">Miro · 2026 ↗</a></article><article><strong>69%</strong><h2>Most AI work happens privately.</h2><p>Say most AI-assisted work happens in private sessions.</p><span>Colleagues may see the finished report without ever seeing the method behind it.</span><a href="${miro}" target="_blank" rel="noopener">Miro · 2026 ↗</a></article><article><strong>85% <small>use AI</small><br>29% <small>embed it in workflows</small></strong><h2>Usage is only the beginning.</h2><p>Using AI is much more common than integrating it into a workflow.</p><span>The work between individual tasks can remain manual.</span><a href="${atlassian}" target="_blank" rel="noopener">Atlassian · 2026 ↗</a></article></div><p class="research-method">Separate self-reported surveys, not one funnel. Parkside is illustrative, not a measured case study.</p>`;}
const discoveryOptions=[
 {id:'reuse',name:'A method worth reusing',title:'Someone already solved work another team still does manually.',people:['priya'],finding:'Priya’s monthly transformation works. Maya at another branch still cleans similar files row by row.',opportunity:'Adapt and test the method, document its rules, add exception handling, and name an owner.',button:'priya',preview:'North.csv + East.xlsx + West.csv → one checked report'},
 {id:'needs',name:'Different help for different people',title:'The same license hides very different needs.',people:['ben','ava','elena'],finding:'Ben developed a strong technique. Ava needs faster access to context. Elena needs a guided way to review her actual updates.',opportunity:'Spread the useful practice, connect the right facts, and build a workflow that helps people check the result.',button:'elena',preview:'Ben: repeatable review · Ava: missing context · Elena: no useful starting point'},
 {id:'handoff',name:'Information that should travel',title:'A department has findings other teams never receive.',people:['nina','marcus','leah'],finding:'Nina reviews recurring issues. Marcus needs relevant account context. Leah still asks around to assemble the broader picture.',opportunity:'Publish reviewed findings into the account record, the assigned action and the weekly briefing.',button:'nina',preview:'Reviewed Ops finding → account context + accountable owner + leadership visibility'}
];
function discoveries(state){const d=discoveryOptions.find(x=>x.id===state.discovery)||discoveryOptions[0];return `<section class="discovery-surface"><nav class="discovery-tabs" aria-label="Choose a discovery">${discoveryOptions.map((x,i)=>`<button data-discovery="${x.id}" aria-pressed="${d.id===x.id}"><small>0${i+1}</small>${x.name}</button>`).join('')}</nav><div class="discovery-content"><div><small>WHAT WE FOUND</small><h2>${d.title}</h2><p>${d.finding}</p><div class="discovery-evidence">${d.preview}</div><div class="discovery-people">${d.people.map(id=>{const p=people.find(x=>x.id===id);return `<button data-workspace="${id}">${p.name} · ${p.department} ↗</button>`;}).join('')}</div></div><aside><small>WHAT THIS COULD BECOME</small><p>${d.opportunity}</p><button class="primary" data-build="${d.button}">See the working improvement →</button><div class="license-comparison"><b>Dana’s adoption report</b><span>All of these employees: license assigned ✓</span><p>The report shows access. Sitting beside people reveals what the company can actually do.</p></div></aside></div></section>`;}
function offer(){return `<section class="engagement"><div class="engagement-stages">${[['01','Discover across departments','Watch real work. Find useful methods, unmet needs and manual handoffs.'],['02','Prioritize with leadership','A company-wide roadmap and a first build with an owner and success measure.'],['03','Build with the employees','Test the workflow with the people who supply, review and use its results.'],['04','Measure and expand','Compare time chasing inputs, time to a usable result, and continued use.']].map(([n,t,p])=>`<section><small>${n}</small><h2>${t}</h2><p>${p}</p></section>`).join('')}</div><div class="invite-list"><div><small>WHO TO BRING</small><p>Operations + IT + two department leaders whose teams depend on each other.</p></div><div><small>WHAT TO BRING</small><p>One example where AI helps. One piece of work your people still chase.</p></div></div><div class="offer-cta"><h2>Book an AI Workflow Discovery Session.</h2><p>See how your teams use AI today and where Nine-67 can make that work useful across the company.</p></div></section>`;}
export function renderScene(state){
 if(state.workspace)return renderWorkspace(state,state.workspace);
 if(state.scene===3)return renderWorkspace(state,'priya');
 if(state.scene===4)return renderWorkspace(state,'ava');
 if(state.scene===5)return renderWorkspace(state,'leah');
 return [board,research,renderCompanyMap,null,null,null,discoveries,renderBuilds,offer][state.scene](state);
}
export function primaryAction(state){return state.scene===8?{label:'Book a discovery session →',action:'discovery'}:{label:`Next · ${['','The research','Meet the company','Private successes','Different needs','Between departments','What we discover','What we build','Where to start'][state.scene+1]} →`,action:'next'};}
export function renderDetail(state,key){
 if(key.startsWith('workspace:')){const id=key.slice(10);const p=people.find(x=>x.id===id);if(p)return {title:`${p.name} · ${p.department}`,html:renderWorkspace(state,id)};}
 if(key.startsWith('source:')){const r=cases.find(x=>x.id===key.slice(7));if(r)return {title:`${r.id} · ${r.account}`,html:`<p class="detail-label">ILLUSTRATIVE ORIGINAL SOURCE · VERSION ${r.version}</p><h3>${e(r.title)}</h3><p>${e(r.description)}</p><p>The reviewer decides whether this source supports the proposed finding.</p><button class="primary" data-exclude="${r.id}" ${state.excluded.includes(r.id)||(r.id==='CASE-201'&&state.builds.nina.published)?'disabled':''}>${r.id==='CASE-201'&&state.builds.nina.published?'Published source preserved':state.excluded.includes(r.id)?'Excluded from optional review':'Exclude from optional review'}</button>`};}
 if(key==='supporting-cases')return {title:'Review supporting cases',html:`<p>Explore the original records. Excluding a record here preserves its source and does not publish a finding.</p><div class="optional-case-list">${cases.filter(r=>r.candidate).map(r=>`<div><button data-detail="source:${r.id}"><b>${r.id} · ${r.account}</b><span>${r.title}</span></button><span>${state.excluded.includes(r.id)?'Excluded':'Available to review'}</span></div>`).join('')}</div>`};
 if(key==='procedure')return {title:'Customer Escalation Procedure · §3',html:'<p class="detail-label">ILLUSTRATIVE APPROVED SHAREPOINT DOCUMENT</p><h3>Transfer ownership without losing context</h3><ol><li>Name a receiving owner.</li><li>Link the original case and relevant implementation notes.</li><li>Record the next customer update date.</li><li>Confirm that the receiving owner accepts the handoff.</li></ol><p>Ask Parkside retrieves this procedure. It does not determine whether each real handoff followed it.</p>'};
 if(key==='research')return {title:'Research behind the story',html:`<p><b>83%</b> of Miro respondents agreed AI made individuals more productive. <b>69%</b> said most AI-assisted work happens in private sessions. <a href="${miro}" target="_blank" rel="noopener">Miro, November 2026 ↗</a></p><p><b>85%</b> of knowledge workers in Atlassian’s survey use AI at work; <b>29%</b> have embedded it into workflows. <a href="${atlassian}" target="_blank" rel="noopener">Atlassian, April 2026 ↗</a></p><p>Different self-reported vendor surveys. These are not measured Nine-67 results.</p>`};
 if(key==='discovery')return {title:'Book an AI Workflow Discovery Session',html:'<p>Bring Operations, IT and two department leaders whose teams depend on each other.</p><p>Each brings one example where AI helps and one piece of work they still chase.</p><div id="booking-content"><b>Type “discovery” in the webinar chat to arrange the session.</b></div><p>Start with company-wide discovery, prioritize a build plan, then implement with the employees who will use it.</p>'};
 return {title:'About this demonstration',html:'<p>Parkside, its employees and every record are fictional. Interfaces, AI responses, file processing and integrations are simulated locally. No live business records or private AI chats are accessed.</p><p>A real build requires approved sources, scoped access, validation, accountable owners and testing with the people doing the work.</p>'};
}
